    out = [row[:] for row in grid]
    seen = set()
    centers = []

    # Each tile is a 4-connected nonzero component.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] != 0 and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        stack.append((yy, xx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            if r1 - r0 != c1 - c0 or r1 - r0 < 2:
                continue
            cy, cx = (r0 + r1) // 2, (c0 + c1) // 2
            centers.append((cy, cx, grid[cy][cx]))

    if not centers:
        return out

    # The most common center color is the ordinary tile; connect only
    # the exceptional center colors.
    counts = {}
    for y, x, color in centers:
        counts[color] = counts.get(color, 0) + 1
    ordinary = max(counts, key=counts.get)
    markers = [(y, x, color) for y, x, color in centers if color != ordinary]

    for i, (y1, x1, color) in enumerate(markers):
        for y2, x2, color2 in markers[i + 1:]:
            if color != color2:
