            active = i < n and occupied(i)
            if active and start is None:
                start = i
            elif not active and start is not None:
                result.append((start, i - 1))
                start = None
        return result

    rb = runs(h, lambda r: any(grid[r][c] for c in range(w)))
    cb = runs(w, lambda c: any(grid[r][c] for r in range(h)))
    tiles = {}

    for ri, (r0, r1) in enumerate(rb):
        for ci, (c0, c1) in enumerate(cb):
            vals = [grid[r][c] for r in range(r0, r1 + 1)
                    for c in range(c0, c1 + 1) if grid[r][c]]
            if not vals:
                continue
            # Ignore partial edge fragments.
            if len(vals) != (r1-r0+1) * (c1-c0+1):
                continue
            from collections import Counter
            counts = Counter(vals)
            border = counts.most_common(1)[0][0]
            inner = [(r, c) for r in range(r0, r1 + 1)
                     for c in range(c0, c1 + 1) if grid[r][c] != border]
            if not inner:
                continue
            core_color = Counter(grid[r][c] for r, c in inner).most_common(1)[0][0]
            core_cells = [(r, c) for r, c in inner if grid[r][c] == core_color]
            tiles[(ri, ci)] = (r0, r1, c0, c1, core_color, core_cells)

    if not tiles:
        return out

    from collections import Counter
    color_counts = Counter(t[4] for t in tiles.values())
    background = color_counts.most_common(1)[0][0]

    # Connect occurrences of each non-background core color across blank
    # separators, without drawing over intervening tiles.
    for color in color_counts:
        if color == background:
            continue
        for ri in range(len(rb)):
            cols = [ci for ci in range(len(cb))
                    if (ri, ci) in tiles and tiles[(ri, ci)][4] == color]
            for a, b in zip(cols, cols[1:]):
                ta, tb = tiles[(ri, a)], tiles[(ri, b)]
                for r, c in ta[5]:
                    for x in range(ta[3] + 1, tb[2]):
                        if out[r][x] == 0:
                            out[r][x] = color

        for ci in range(len(cb)):
            rows = [ri for ri in range(len(rb))
                    if (ri, ci) in tiles and tiles[(ri, ci)][4] == color]
            for a, b in zip(rows, rows[1:]):
                ta, tb = tiles[(a, ci)], tiles[(b, ci)]
                for r, c in ta[5]:
                    for y in range(ta[1] + 1, tb[0]):
                        if out[y][c] == 0:
                            out[y][c] = color

    return out
